29	/**
30	 * NO GLOBAL `fetch` ON THIS RUNTIME (found live, 2026-08-26). This machine
31	 * runs Node 16, where `fetch` is undefined — the call threw ReferenceError
32	 * and the catch below reported it as an unreachable host. A live service
33	 * was being called dead. The stdlib client is used whenever `fetch` is
34	 * absent; behaviour is otherwise identical.
35	 */
36	function stdlibPostJson(url: string, payload: string, headers: Record<string, string>, timeoutMs: number): Promise<{ status: number; bodyText: string }> {
37	  return new Promise((resolvePromise, rejectPromise) => {
38	    const parsed = new URL(url);
39	    const isHttps = parsed.protocol === "https:";
40	    const client = isHttps ? httpsRequest : httpRequest;
41	    const request = client(
42	      {
43	        hostname: parsed.hostname,
44	        port: parsed.port !== "" ? Number(parsed.port) : isHttps ? 443 : 80,
45	        path: `${parsed.pathname}${parsed.search}`,
46	        method: "POST",
47	        headers: { ...headers, "Content-Length": String(Buffer.byteLength(payload)) },
48	        timeout: timeoutMs,
49	      },
50	      (res) => {
51	        let text = "";
52	        res.setEncoding("utf8");
53	        res.on("data", (chunk: string) => { text += chunk; });
54	        res.on("end", () => resolvePromise({ status: res.statusCode ?? 0, bodyText: text }));
55	      },
56	    );
57	    request.on("timeout", () => { request.destroy(); rejectPromise(new Error(`no answer within ${timeoutMs}ms`)); });
58	    request.on("error", (error) => rejectPromise(error));
59	    request.write(payload);
60	    request.end();
61	  });
62	}
63	
64	export async function httpPostJson(
65	  url: string,
66	  headers: Readonly<Record<string, string>>,
67	  body: unknown,
68	  timeoutMs: number,
69	): Promise<HttpResult> {
70	  const controller = new AbortController();
71	  const timer = setTimeout(() => controller.abort(), timeoutMs);
72	  try {
73	    if (typeof fetch !== "function") {
74	      const viaStdlib = await stdlibPostJson(url, JSON.stringify(body), { "Content-Type": "application/json", ...headers }, timeoutMs);
75	      return { reached: true, status: viaStdlib.status, bodyText: viaStdlib.bodyText, detail: `HTTP ${viaStdlib.status}` };
76	    }
77	    const response = await fetch(url, {
78	      method: "POST",
79	      headers: { "Content-Type": "application/json", ...headers },
80	      body: JSON.stringify(body),
81	      signal: controller.signal,
82	    });
83	    const bodyText = await response.text();
84	    return { reached: true, status: response.status, bodyText, detail: `HTTP ${response.status}` };
85	  } catch (error) {
86	    const reason = error instanceof Error ? (error.name === "AbortError" ? `no answer within ${timeoutMs}ms` : error.message) : String(error);
