63	  const unconfigured = await fetchAlertEmails({ ...CONFIG, endpoint_url: "", secret_value: "" }, "from:notify.railway.app");
64	  check("C1. missing endpoint/secret -> NOT_CONFIGURED, zero emails", !unconfigured.ok && unconfigured.emails.length === 0, unconfigured);
65	
66	  // ===== D. UNREACHABLE UPSTREAM IS REPORTED, NOT WORKED AROUND =====
67	  const unreachable = await fetchAlertEmails({ ...CONFIG, endpoint_url: "http://127.0.0.1:1/none", timeout_ms: 2_000 }, "from:notify.railway.app");
