{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01NMpxuDhhFW1eke317FtsMP","type":"tool_result","content":"1	/**
2	 * หน้าที่: proves the EMAIL INPUT ADAPTER (a) reimplements no Gmail
3	 * reading, (b) translates the existing reader's real output shape into
4	 * `control/alert-correlation/`'s input, and (c) fails honestly instead of
5	 * falling back to reading mail itself.
6	 *
7	 * The end-to-end case feeds a translated message straight into the real
8	 * `runAlertCorrelation`, proving the two contracts actually join — the
9	 * seam is the point of this folder, so a test that only checked field
10	 * names would prove nothing.
11	 *
12	 * How to run (needs Node >=18 for global fetch):
13	 *   npx tsx connections/email-alert-source/tests/adapter.test.ts
14	 */
15	
16	import { readFileSync } from "node:fs";
17	import { join, dirname } from "node:path";
18	import { fileURLToPath } from "node:url";
19	import { fetchAlertEmails, type EmailSourceConfig } from "../contract";
20	import { runAlertCorrelation } from "../../../control/alert-correlation/contract";
21	
22	let passed = 0;
23	let failed = 0;
24	function check(name: string, condition: boolean, detail?: unknown): void {
25	  if (condition) { passed++; console.log(`PASS  ${name}`); }
26	  else { failed++; console.error(`FAIL  ${name}`); if (detail !== undefined) console.error("      " + JSON.stringify(detail).slice(0, 300)); }
27	}
28	
29	const FOLDER = join(dirname(fileURLToPath(import.meta.url)), "..");
30	const CONFIG: EmailSourceConfig = {
31	  endpoint_url: "https://vibrant-hawking.supabase.co/functions/v1/provider-alert-email-read",
32	  secret_header_name: "x-provider-alert-email-secret",
33	  secret_value: "not-a-real-secret",
34	  timeout_ms: 3_000,
35	};
36	
37	async function main(): Promise<void> {
38	  // ===== A. NO DUPLICATE GMAIL READER — real source scan =====
39	  const sources = ["adapter.ts", "types.ts", "host-runtime.ts", "contract.ts"];
40	  /**
41	   * Comments MUST be stripped before scanning. These files deliberately
42	   * document what they do NOT do ("no oauth2.googleapis call", "never add
43	   * GMAIL_CLIENT_ID"), so scanning raw text flags the very prose that
44	   * promises the opposite — a false positive that would make this test
45	   * meaningless. Scan the CODE, not the explanation of the code.
46	   */
47	  const stripComments = (src: string): string => src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
48	  const readerMarkers = /oauth2\.googleapis|gmail\.googleapis|googleapis\.com|users\.messages|refresh_token|GMAIL_CLIENT|nodemailer|imapflow|require\(["']imap|from\s+["']imap/i;
49	  const offenders = sources.filter((f) => readerMarkers.test(stripComments(readFileSync(join(FOLDER, f), "utf-8"))));
50	  check("A1. no Gmail/OAuth/IMAP client exists in this adapter", offenders.length === 0, offenders);
51	  check(
52	    "A2. no Google credential name appears anywhere in this folder",
53	    !sources.some((f) => /GMAIL_(CLIENT_ID|CLIENT_SECRET|REFRESH_TOKEN)/.test(readFileSync(join(FOLDER, f), "utf-8"))),
54	  );
55	
56	  // ===== B. UNSCOPED QUERIES ARE REFUSED (no whole-inbox reads) =====
57	  const unscoped = await fetchAlertEmails(CONFIG, "");
58	  check("B1. an empty query is refused", !unscoped.ok && unscoped.error_code === "NOT_CONFIGURED", unscoped.error_code);
59	  const broad = await fetchAlertEmails(CONFIG, "is:unread");
60	  check("B2. a non-deterministic query ('is:unread') is refused", !broad.ok && broad.error_code === "NOT_CONFIGURED", broad.detail);
61	
62	  // ===== C. MISSING CONFIG FAILS CLOSED, NEVER FALLS BACK =====
63	  const unconfigured = await fetchAlertEmails({ ...CONFIG, endpoint_url: "", secret_value: "" }, "from:notify.railway.app");
64	  check("C1. missing endpoint/secret -> NOT_CONFIGURED, zero emails", !unconfigured.ok && unconfigured.emails.length === 0, unconfigured);
65	
66	  // ===== D. UNREACHABLE UPSTREAM IS REPORTED, NOT WORKED AROUND =====
67	  const unreachable = await fetchAlertEmails({ ...CONFIG, endpoint_url: "http://127.0.0.1:1/none", timeout_ms: 2_000 }, "from:notify.railway.app");
68	  check("D1. an unreachable reader -> UNREACHABLE (no direct-Gmail fallback)", !unreachable.ok && unreachable.error_code === "UNREACHABLE", unreachable.error_code);
69	  check("D2. provenance is recorded even on failure", unreachable.source_endpoint.length > 0 && unreachable.fetched_at.length > 0);
70	
71	  // ===== E. TRANSLATION JOINS THE TWO CONTRACTS =====
72	  // Real upstream shape: exactly what _shared/gmail-client.ts already
73	  // produces (fetchGmailMessage + getSubjectHeader + extractBodyText),
74	  // carrying the REAL Railway alert from thread 1a03cb91688a2d24.
